22→/**
23→ * Result of an IPFS upload operation.
24→ */
25→export type IpfsAddResult = {
26→  cid: string;
27→  size: number;
28→  recorded: boolean;
29→};
30→
31→/**
32→ * Progress callback for upload/download operations.
33→ */
34→export type ProgressCallback = (percent: number) => void;
35→export type DownloadProgressCallback = (loaded: number, total: number) => void;
