278→  async getPendingRotations(sharerId: string): Promise<Share[]> {
279→    return this.shareRepo.find({
280→      where: {
281→        sharerId,
282→        revokedAt: Not(IsNull()),
283→      },
284→      relations: ['recipient'],
285→      order: { revokedAt: 'ASC' },
286→    });
