/**
 * Error Cases Tests
 *
 * Tests negative paths: expired tokens, unloaded folders,
 * BinNotLoadedError, and various edge cases.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { CipherBoxClient, BinNotLoadedError } from '@cipherbox/sdk';
import {
  createTestContext,
  deleteTestAccount,
  type TestContext,
  API_URL,
} from '../fixtures/test-harness';
import { generateTextContent } from '../helpers/data-generators';

describe('Error Cases', () => {
  let ctx: TestContext;

  beforeAll(async () => {
    ctx = await createTestContext('error-cases');
  });

  afterAll(async () => {
    if (ctx) {
      ctx.cleanup();
      await deleteTestAccount(ctx);
    }
  });

  describe('Unloaded folder operations', () => {
    const fakeIpnsName = 'k51qzi5uqu5fake000000000000000000000000000000000000';

    it('should throw on createFolder with unloaded parent', async () => {
      await expect(
        ctx.client.createFolder(fakeIpnsName, 'Test')
      ).rejects.toThrow('Parent folder not loaded');
    });

    it('should throw on renameItem with unloaded folder', async () => {
      await expect(
        ctx.client.renameItem(fakeIpnsName, 'child-id', 'new-name')
      ).rejects.toThrow('Folder not loaded');
    });

    it('should throw on deleteItem with unloaded folder', async () => {
      await expect(
        ctx.client.deleteItem(fakeIpnsName, 'child-id')
      ).rejects.toThrow('Folder not loaded');
    });

    it('should throw on uploadFile with unloaded folder', async () => {
      await expect(
        ctx.client.uploadFile(fakeIpnsName, new Uint8Array(10), 'test.txt', 'text/plain')
      ).rejects.toThrow('Folder not loaded');
    });

    it('should throw on moveItem with unloaded source', async () => {
      await expect(
        ctx.client.moveItem(fakeIpnsName, ctx.rootIpnsName, 'child-id')
      ).rejects.toThrow('Source folder not loaded');
    });

    it('should throw on moveItem with unloaded destination', async () => {
      await expect(
        ctx.client.moveItem(ctx.rootIpnsName, fakeIpnsName, 'child-id')
      ).rejects.toThrow();
    });
  });

  describe('Bin operations without loadBin', () => {
    it('should throw BinNotLoadedError on deleteToBin', async () => {
      const freshCtx = await createTestContext('bin-err-1');
      try {
        await expect(
          freshCtx.client.deleteToBin(freshCtx.rootIpnsName, 'id', 'path')
        ).rejects.toThrow('Bin not loaded');

        // Verify it's the right error type
        try {
          await freshCtx.client.deleteToBin(freshCtx.rootIpnsName, 'id', 'path');
        } catch (err) {
          expect(err).toBeInstanceOf(BinNotLoadedError);
        }
      } finally {
        freshCtx.cleanup();
        await deleteTestAccount(freshCtx);
      }
    });

    it('should throw BinNotLoadedError on restoreFromBin', async () => {
      const freshCtx = await createTestContext('bin-err-2');
      try {
        await expect(
          freshCtx.client.restoreFromBin('entry-id', freshCtx.rootIpnsName)
        ).rejects.toThrow('Bin not loaded');
      } finally {
        freshCtx.cleanup();
        await deleteTestAccount(freshCtx);
      }
    });

    it('should throw BinNotLoadedError on permanentDelete', async () => {
      const freshCtx = await createTestContext('bin-err-3');
      try {
        await expect(
          freshCtx.client.permanentDelete('entry-id')
        ).rejects.toThrow('Bin not loaded');
      } finally {
        freshCtx.cleanup();
        await deleteTestAccount(freshCtx);
      }
    });

    it('should throw BinNotLoadedError on emptyBin', async () => {
      const freshCtx = await createTestContext('bin-err-4');
      try {
        await expect(freshCtx.client.emptyBin()).rejects.toThrow('Bin not loaded');
      } finally {
        freshCtx.cleanup();
        await deleteTestAccount(freshCtx);
      }
    });
  });

  describe('Event emission', () => {
    it('should emit operation:start and operation:end events', async () => {
      const events: any[] = [];
      const unsub = ctx.client.on((event) => events.push(event));

      await ctx.client.createFolder(ctx.rootIpnsName, 'EventTest');

      unsub();

      const starts = events.filter((e) => e.type === 'operation:start');
      const ends = events.filter((e) => e.type === 'operation:end');

      expect(starts.length).toBeGreaterThan(0);
      expect(ends.length).toBeGreaterThan(0);
      expect(starts[0].operation).toBe('createFolder');
      expect(ends[0].operation).toBe('createFolder');
      expect(ends[0].durationMs).toBeTypeOf('number');
    });

    it('should emit error events on failure', async () => {
      const events: any[] = [];
      const unsub = ctx.client.on((event) => events.push(event));

      try {
        await ctx.client.createFolder('k51nonexistent', 'WillFail');
      } catch {
        // Expected
      }

      unsub();

      const errors = events.filter((e) => e.type === 'error');
      expect(errors.length).toBe(1);
      expect(errors[0].operation).toBe('createFolder');
      expect(errors[0].error).toBeInstanceOf(Error);
    });
  });

  describe('Client lifecycle', () => {
    it('should not work after destroy()', async () => {
      const tempCtx = await createTestContext('destroy-test');

      // Should work before destroy
      const folder = await tempCtx.client.createFolder(tempCtx.rootIpnsName, 'PreDestroy');
      expect(folder.id).toBeTruthy();

      // Destroy
      tempCtx.client.destroy();

      // Operations should fail after destroy (keys are zeroed)
      await expect(
        tempCtx.client.createFolder(tempCtx.rootIpnsName, 'PostDestroy')
      ).rejects.toThrow();

      await deleteTestAccount(tempCtx);
    });
  });
});

/**
 * Invite Link Tests
 *
 * Tests invite link creation, public status check, claim flow,
 * double-claim prevention, and revocation.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { wrapKey, bytesToHex } from '@cipherbox/crypto';
import {
  createMultiAccountFixture,
  type MultiAccountFixture,
} from '../fixtures/multi-account';
import { API_URL } from '../fixtures/test-harness';

describe('Invite Link', () => {
  let fixture: MultiAccountFixture;

  beforeAll(async () => {
    fixture = await createMultiAccountFixture(['alice', 'bob', 'charlie']);
  });

  afterAll(async () => {
    if (fixture) await fixture.cleanupAll();
  });

  let inviteId: string;
  let inviteToken: string;
  let folderIpnsName: string;

  it('should create an invite link', async () => {
    const alice = fixture.accounts.get('alice')!;
    fixture.switchTo('alice');

    // Create a folder to share via invite
    const folder = await alice.client.createFolder(alice.rootIpnsName, 'InviteFolder');
    folderIpnsName = folder.ipnsName;

    // Wrap with a dummy key (in real flow, this would be an ephemeral keypair)
    const encryptedKey = await wrapKey(folder.folderKey, alice.publicKey);

    const res = await fetch(`${API_URL}/shares/invites`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${alice.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        itemType: 'folder',
        ipnsName: folder.ipnsName,
        itemName: 'InviteFolder',
        encryptedKey: bytesToHex(encryptedKey),
      }),
    });

    expect(res.status).toBe(201);
    const data = await res.json();
    expect(data.id).toBeTruthy();
    expect(data.token).toBeTruthy();
    expect(data.status).toBe('active');
    inviteId = data.id;
    inviteToken = data.token;
  });

  it('should show active status publicly (no auth)', async () => {
    const res = await fetch(`${API_URL}/invites/${inviteToken}`);
    expect(res.ok).toBe(true);

    const data = await res.json();
    expect(data.status).toBe('active');
  });

  it('should return invite data for authenticated user', async () => {
    const bob = fixture.accounts.get('bob')!;

    const res = await fetch(`${API_URL}/invites/${inviteToken}/data`, {
      headers: { Authorization: `Bearer ${bob.accessToken}` },
    });
    expect(res.ok).toBe(true);

    const data = await res.json();
    expect(data.status).toBe('active');
    expect(data.itemType).toBe('folder');
    expect(data.ipnsName).toBe(folderIpnsName);
    expect(data.itemName).toBe('InviteFolder');
    expect(data.encryptedKey).toBeTruthy();
  });

  it('should allow Bob to claim the invite', async () => {
    const bob = fixture.accounts.get('bob')!;
    fixture.switchTo('bob');

    // Re-wrap the key for Bob (simplified — in real flow, decrypt ephemeral then re-encrypt)
    const dummyReWrappedKey = bytesToHex(new Uint8Array(64).fill(0xab));

    const res = await fetch(`${API_URL}/invites/${inviteToken}/claim`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${bob.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        encryptedKey: dummyReWrappedKey,
      }),
    });

    expect(res.status).toBe(201);
    const data = await res.json();
    expect(data.shareId).toBeTruthy();
  });

  it('should reject double-claim by another user', async () => {
    const charlie = fixture.accounts.get('charlie')!;

    const res = await fetch(`${API_URL}/invites/${inviteToken}/claim`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${charlie.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        encryptedKey: bytesToHex(new Uint8Array(64).fill(0xcd)),
      }),
    });

    // Should be 409 (already claimed) or 404 (no longer active)
    expect([404, 409]).toContain(res.status);
  });

  it('should reject double-claim by same user', async () => {
    const bob = fixture.accounts.get('bob')!;

    const res = await fetch(`${API_URL}/invites/${inviteToken}/claim`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${bob.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        encryptedKey: bytesToHex(new Uint8Array(64).fill(0xef)),
      }),
    });

    expect([404, 409]).toContain(res.status);
  });

  it('should allow Alice to create and revoke a new invite', async () => {
    const alice = fixture.accounts.get('alice')!;
    fixture.switchTo('alice');

    const encryptedKey = bytesToHex(new Uint8Array(64).fill(0x11));

    const createRes = await fetch(`${API_URL}/shares/invites`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${alice.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        itemType: 'folder',
        ipnsName: folderIpnsName,
        itemName: 'InviteFolder',
        encryptedKey,
      }),
    });
    expect(createRes.status).toBe(201);
    const newInvite = await createRes.json();

    // Revoke it
    const revokeRes = await fetch(`${API_URL}/shares/invites/${newInvite.id}`, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${alice.accessToken}` },
    });
    expect(revokeRes.status).toBe(204);

    // Public status should now be 404
    const statusRes = await fetch(`${API_URL}/invites/${newInvite.token}`);
    expect(statusRes.status).toBe(404);
  });
});

