    const encryptedKey = await wrapKey(folder.folderKey, alice.publicKey);

    const res = await fetch(`${API_URL}/shares/invites`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${alice.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        itemType: 'folder',
        ipnsName: folder.ipnsName,
        itemName: 'InviteFolder',
        encryptedKey: bytesToHex(encryptedKey),
      }),
    });

    expect(res.status).toBe(201);
    const data = await res.json();
    expect(data.id).toBeTruthy();
    expect(data.token).toBeTruthy();
    expect(data.status).toBe('active');
    inviteId = data.id;
    inviteToken = data.token;
  });

  it('should show active status publicly (no auth)', async () => {
    const res = await fetch(`${API_URL}/invites/${inviteToken}`);
    expect(res.ok).toBe(true);

    const data = await res.json();
    expect(data.status).toBe('active');
  });

  it('should return invite data for authenticated user', async () => {
    const bob = fixture.accounts.get('bob')!;

    const res = await fetch(`${API_URL}/invites/${inviteToken}/data`, {
      headers: { Authorization: `Bearer ${bob.accessToken}` },
    });
    expect(res.ok).toBe(true);

    const data = await res.json();
    expect(data.status).toBe('active');
    expect(data.itemType).toBe('folder');
    expect(data.ipnsName).toBe(folderIpnsName);
    expect(data.itemName).toBe('InviteFolder');
    expect(data.encryptedKey).toBeTruthy();
  });

  it('should allow Bob to claim the invite', async () => {
    const bob = fixture.accounts.get('bob')!;
    fixture.switchTo('bob');

    // Re-wrap the key for Bob (simplified — in real flow, decrypt ephemeral then re-encrypt)
    const dummyReWrappedKey = bytesToHex(new Uint8Array(64).fill(0xab));

    const res = await fetch(`${API_URL}/invites/${inviteToken}/claim`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${bob.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        encryptedKey: dummyReWrappedKey,
      }),
    });

    expect(res.status).toBe(201);
    const data = await res.json();
    expect(data.shareId).toBeTruthy();
  });

  it('should reject double-claim by another user', async () => {
    const charlie = fixture.accounts.get('charlie')!;

    const res = await fetch(`${API_URL}/invites/${inviteToken}/claim`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${charlie.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        encryptedKey: bytesToHex(new Uint8Array(64).fill(0xcd)),
      }),
    });

    // Should be 409 (already claimed) or 404 (no longer active)
    expect([404, 409]).toContain(res.status);
  });

  it('should reject double-claim by same user', async () => {
    const bob = fixture.accounts.get('bob')!;

    const res = await fetch(`${API_URL}/invites/${inviteToken}/claim`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${bob.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        encryptedKey: bytesToHex(new Uint8Array(64).fill(0xef)),
      }),
    });

    expect([404, 409]).toContain(res.status);
  });

  it('should allow Alice to create and revoke a new invite', async () => {
    const alice = fixture.accounts.get('alice')!;
    fixture.switchTo('alice');

    const encryptedKey = bytesToHex(new Uint8Array(64).fill(0x11));

    const createRes = await fetch(`${API_URL}/shares/invites`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${alice.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        itemType: 'folder',
        ipnsName: folderIpnsName,
        itemName: 'InviteFolder',
        encryptedKey,
      }),
    });
    expect(createRes.status).toBe(201);
    const newInvite = await createRes.json();

    // Revoke it
    const revokeRes = await fetch(`${API_URL}/shares/invites/${newInvite.id}`, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${alice.accessToken}` },
    });
    expect(revokeRes.status).toBe(204);

    // Public status should now be 404
    const statusRes = await fetch(`${API_URL}/invites/${newInvite.token}`);
    expect(statusRes.status).toBe(404);
  });
});

/**
 * IPNS Consistency Tests
 *
 * Tests IPNS publish, resolve, sequence number increment,
 * and folder metadata persistence through the IPNS layer.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import {
  createTestContext,
  deleteTestAccount,
  type TestContext,
} from '../fixtures/test-harness';
import { getChild, expectChildCount } from '../helpers/assertions';
import { generateTextContent } from '../helpers/data-generators';

describe('IPNS Consistency', () => {
  let ctx: TestContext;

  beforeAll(async () => {
    ctx = await createTestContext('ipns-consistency');
  });

  afterAll(async () => {
    if (ctx) {
      ctx.cleanup();
      await deleteTestAccount(ctx);
    }
  });

  it('should increment sequence number on each folder mutation', async () => {
    const seq0 = ctx.client.getFolderSequenceNumber(ctx.rootIpnsName);
    expect(seq0).toBe(0n);

    await ctx.client.createFolder(ctx.rootIpnsName, 'SeqTest1');
    const seq1 = ctx.client.getFolderSequenceNumber(ctx.rootIpnsName);
    expect(seq1).toBeGreaterThan(seq0!);

    await ctx.client.createFolder(ctx.rootIpnsName, 'SeqTest2');
    const seq2 = ctx.client.getFolderSequenceNumber(ctx.rootIpnsName);
    expect(seq2).toBeGreaterThan(seq1!);

    await ctx.client.createFolder(ctx.rootIpnsName, 'SeqTest3');
    const seq3 = ctx.client.getFolderSequenceNumber(ctx.rootIpnsName);
    expect(seq3).toBeGreaterThan(seq2!);
  });

  it('should persist folder children through IPNS publish/resolve', async () => {
    // Verify that loadFolder resolves the metadata we just published
    const loaded = await ctx.client.loadFolder(
      ctx.rootIpnsName,
      ctx.rootFolderKey,
      ctx.rootIpnsKeypair
    );

    expect(loaded).toBeTruthy();
    expect(loaded!.children.length).toBe(3); // SeqTest1, SeqTest2, SeqTest3

    const names = loaded!.children.map((c) => c.name).sort();
    expect(names).toEqual(['SeqTest1', 'SeqTest2', 'SeqTest3']);
  });

  it('should persist file upload through IPNS', async () => {
    const content = generateTextContent('IPNS persistence test');
    await ctx.client.uploadFile(
      ctx.rootIpnsName,
      content,
      'ipns-test.txt',
      'text/plain'
    );

    // Reload from IPNS to verify persistence
    const loaded = await ctx.client.loadFolder(
      ctx.rootIpnsName,
      ctx.rootFolderKey,
      ctx.rootIpnsKeypair
    );

    expect(loaded).toBeTruthy();
    const file = loaded!.children.find((c) => c.name === 'ipns-test.txt');
    expect(file).toBeTruthy();
    expect(file!.type).toBe('file');
  });

  it('should persist rename through IPNS', async () => {
    const child = getChild(ctx.client, ctx.rootIpnsName, 'SeqTest1');
    await ctx.client.renameItem(ctx.rootIpnsName, child.id, 'RenamedSeq');

    // Reload and verify
    const loaded = await ctx.client.loadFolder(
      ctx.rootIpnsName,
      ctx.rootFolderKey,
      ctx.rootIpnsKeypair
    );

    expect(loaded).toBeTruthy();
    const renamed = loaded!.children.find((c) => c.name === 'RenamedSeq');
    expect(renamed).toBeTruthy();
    const original = loaded!.children.find((c) => c.name === 'SeqTest1');
    expect(original).toBeUndefined();
  });

  it('should persist delete through IPNS', async () => {
    const before = await ctx.client.loadFolder(
      ctx.rootIpnsName,
      ctx.rootFolderKey,
      ctx.rootIpnsKeypair
    );
    const countBefore = before!.children.length;

    const child = getChild(ctx.client, ctx.rootIpnsName, 'RenamedSeq');
    await ctx.client.deleteItem(ctx.rootIpnsName, child.id);

    const after = await ctx.client.loadFolder(
      ctx.rootIpnsName,
      ctx.rootFolderKey,
      ctx.rootIpnsKeypair
    );
    expect(after!.children.length).toBe(countBefore - 1);
  });

  it('should maintain sequence number monotonicity after many operations', async () => {
    let prevSeq = ctx.client.getFolderSequenceNumber(ctx.rootIpnsName)!;

    // Rapid folder create-delete cycles
    for (let i = 0; i < 5; i++) {
      const folder = await ctx.client.createFolder(ctx.rootIpnsName, `Rapid-${i}`);
      const newSeq = ctx.client.getFolderSequenceNumber(ctx.rootIpnsName)!;
      expect(newSeq).toBeGreaterThan(prevSeq);
      prevSeq = newSeq;

      await ctx.client.deleteItem(ctx.rootIpnsName, folder.id);
      const afterDelete = ctx.client.getFolderSequenceNumber(ctx.rootIpnsName)!;
      expect(afterDelete).toBeGreaterThan(prevSeq);
      prevSeq = afterDelete;
    }
  });
});

