1294→+/**
1295→+ * File Upload/Download Workload
1296→+ *
1297→+ * Parameterized workload that uploads and downloads files of varying sizes.
1298→+ */
1299→+
1300→+import type { PoolClient } from '../harness/client-pool';
1301→+
1302→+export interface FileWorkloadOptions {
1303→+  /** Number of files to upload */
1304→+  fileCount: number;
1305→+  /** Min file size in bytes */
1306→+  minSize: number;
1307→+  /** Max file size in bytes */
1308→+  maxSize: number;
1309→+  /** Whether to verify downloads after upload */
1310→+  verifyDownloads: boolean;
1311→+}
1312→+
1313→+/**
1314→+ * Run a file upload workload on a single client.
1315→+ */
1316→+export async function runFileWorkload(pc: PoolClient, opts: FileWorkloadOptions): Promise<void> {
1317→+  const { fileCount, minSize, maxSize, verifyDownloads } = opts;
1318→+  const { client, rootIpnsName, rootFolderKey, metrics } = pc;
1319→+
1320→+  for (let i = 0; i < fileCount; i++) {
1321→+    const size = minSize + Math.floor(Math.random() * (maxSize - minSize));
1322→+    const data = new Uint8Array(size);
1323→+    crypto.getRandomValues(data);
1324→+    const fileName = `load-${pc.id}-file-${i}-${size}b.bin`;
1325→+
1326→+    // Upload
1327→+    await metrics.measure(
1328→+      'uploadFile',
1329→+      () => client.uploadFile(rootIpnsName, data, fileName, 'application/octet-stream'),
1330→+      size
1331→+    );
1332→+
1333→+    // Optionally download and verify
1334→+    if (verifyDownloads) {
1335→+      const folder = (client as any).folderTree.get(rootIpnsName);
1336→+      const child = folder?.children.find((c: any) => c.name === fileName);
1337→+      if (child?.fileMetaIpnsName) {
1338→+        const downloaded = await metrics.measure(
1339→+          'downloadFile',
1340→+          () => client.downloadFromIpns(child.fileMetaIpnsName, rootFolderKey),
1341→+          size
1342→+        );
1343→+        if (downloaded.length !== data.length) {
1344→+          throw new Error(
1345→+            `Size mismatch: uploaded ${data.length}, downloaded ${downloaded.length}`
1346→+          );
1347→+        }
1348→+      }
1349→+    }
1350→+  }
1351→+}
