1403→+/**
1404→+ * Mixed Workload
1405→+ *
1406→+ * Simulates realistic usage: a mix of folder CRUD, file uploads,
1407→+ * renames, moves, and deletes with weighted probabilities.
1408→+ */
1409→+
1410→+import type { PoolClient } from '../harness/client-pool';
1411→+
1412→+export interface MixedWorkloadOptions {
1413→+  /** Total number of operations */
1414→+  totalOps: number;
1415→+  /** Operation weights (sum doesn't need to be 1, they're normalized) */
1416→+  weights?: {
1417→+    createFolder?: number;
1418→+    uploadFile?: number;
1419→+    renameItem?: number;
1420→+    moveItem?: number;
1421→+    deleteItem?: number;
1422→+  };
1423→+}
1424→+
1425→+const DEFAULT_WEIGHTS = {
1426→+  createFolder: 2,
1427→+  uploadFile: 4,
1428→+  renameItem: 1,
1429→+  moveItem: 1,
1430→+  deleteItem: 1,
1431→+};
1432→+
1433→+/**
1434→+ * Run a mixed workload on a single client.
1435→+ */
1436→+export async function runMixedWorkload(pc: PoolClient, opts: MixedWorkloadOptions): Promise<void> {
1437→+  const { client, rootIpnsName, metrics } = pc;
1438→+  const weights = { ...DEFAULT_WEIGHTS, ...opts.weights };
1439→+  const totalWeight = Object.values(weights).reduce((a, b) => a + b, 0);
1440→+
1441→+  // Track created items for rename/move/delete targets
1442→+  const folderIds: Array<{
1443→+    id: string;
1444→+    ipnsName: string;
1445→+    folderKey: Uint8Array;
1446→+    ipnsPrivateKey: Uint8Array;
1447→+  }> = [];
1448→+  const fileIds: Array<{ id: string; name: string }> = [];
1449→+
1450→+  for (let i = 0; i < opts.totalOps; i++) {
1451→+    const roll = Math.random() * totalWeight;
1452→+    let cumulative = 0;
1453→+
1454→+    // Pick operation based on weighted random
1455→+    if ((cumulative += weights.createFolder) > roll) {
1456→+      // Create folder
1457→+      try {
1458→+        const name = `mix-folder-${pc.id}-${i}`;
1459→+        const folder = await metrics.measure('createFolder', () =>
1460→+          client.createFolder(rootIpnsName, name)
1461→+        );
1462→+        folderIds.push(folder);
1463→+      } catch {
1464→+        /* non-fatal */
1465→+      }
1466→+    } else if ((cumulative += weights.uploadFile) > roll) {
1467→+      // Upload file
1468→+      try {
1469→+        const size = 1024 + Math.floor(Math.random() * 50_000);
1470→+        const data = new Uint8Array(size);
1471→+        crypto.getRandomValues(data);
1472→+        const fileName = `mix-file-${pc.id}-${i}.bin`;
1473→+
1474→+        await metrics.measure(
1475→+          'uploadFile',
1476→+          () => client.uploadFile(rootIpnsName, data, fileName, 'application/octet-stream'),
1477→+          size
1478→+        );
1479→+
1480→+        const folder = (client as any).folderTree.get(rootIpnsName);
1481→+        const child = folder?.children.find((c: any) => c.name === fileName);
1482→+        if (child) fileIds.push({ id: child.id, name: fileName });
1483→+      } catch {
1484→+        /* non-fatal */
1485→+      }
1486→+    } else if ((cumulative += weights.renameItem) > roll) {
1487→+      // Rename a random file
1488→+      if (fileIds.length > 0) {
1489→+        const idx = Math.floor(Math.random() * fileIds.length);
1490→+        const target = fileIds[idx];
1491→+        const newName = `${target.name}-r${i}`;
1492→+        try {
1493→+          await metrics.measure('renameItem', () =>
1494→+            client.renameItem(rootIpnsName, target.id, newName)
1495→+          );
1496→+          fileIds[idx] = { ...target, name: newName };
1497→+        } catch {
1498→+          /* non-fatal */
1499→+        }
1500→+      }
1501→+    } else if ((cumulative += weights.moveItem) > roll) {
1502→+      // Move a file into a folder (if both exist)
1503→+      if (fileIds.length > 0 && folderIds.length > 0) {
1504→+        const fileIdx = Math.floor(Math.random() * fileIds.length);
1505→+        const folderIdx = Math.floor(Math.random() * folderIds.length);
1506→+        const targetFolder = folderIds[folderIdx];
1507→+
1508→+        // Ensure target folder is registered
1509→+        if (!client.hasFolder(targetFolder.ipnsName)) {
1510→+          client.registerFolder(
1511→+            targetFolder.ipnsName,
1512→+            targetFolder.folderKey,
1513→+            { publicKey: new Uint8Array(0), privateKey: targetFolder.ipnsPrivateKey },
1514→+            [],
1515→+            1n
1516→+          );
1517→+        }
1518→+
1519→+        try {
1520→+          await metrics.measure('moveItem', () =>
1521→+            client.moveItem(rootIpnsName, targetFolder.ipnsName, fileIds[fileIdx].id)
1522→+          );
1523→+          fileIds.splice(fileIdx, 1); // Remove from root tracking
1524→+        } catch {
1525→+          /* non-fatal */
1526→+        }
1527→+      }
1528→+    } else {
1529→+      // Delete a random item
1530→+      if (fileIds.length > 0) {
1531→+        const idx = Math.floor(Math.random() * fileIds.length);
1532→+        try {
1533→+          await metrics.measure('deleteItem', () =>
1534→+            client.deleteItem(rootIpnsName, fileIds[idx].id)
1535→+          );
1536→+          fileIds.splice(idx, 1);
1537→+        } catch {
1538→+          /* non-fatal */
1539→+        }
1540→+      } else if (folderIds.length > 0) {
1541→+        const idx = Math.floor(Math.random() * folderIds.length);
1542→+        try {
1543→+          await metrics.measure('deleteItem', () =>
1544→+            client.deleteItem(rootIpnsName, folderIds[idx].id)
1545→+          );
1546→+          folderIds.splice(idx, 1);
1547→+        } catch {
1548→+          /* non-fatal */
1549→+        }
1550→+      }
1551→+    }
1552→+  }
1553→+}
