1920→+/**
1921→+ * Test data generators for SDK E2E tests.
1922→+ * All data is in-memory Uint8Array — no filesystem temp files needed.
1923→+ */
1924→+
1925→+/**
1926→+ * Generate a Uint8Array of the given size filled with a repeating pattern.
1927→+ * The pattern is deterministic for a given seed, enabling content verification.
1928→+ */
1929→+export function generateBytes(sizeBytes: number, seed = 42): Uint8Array {
1930→+  const data = new Uint8Array(sizeBytes);
1931→+  for (let i = 0; i < sizeBytes; i++) {
1932→+    data[i] = (seed + i * 7 + (i >> 8) * 13) & 0xff;
1933→+  }
1934→+  return data;
1935→+}
