  1→/**
  2→ * Load Test Client Pool
  3→ *
  4→ * Manages N CipherBoxClient instances, each with its own test account.
  5→ * Creates accounts in parallel, distributes workloads, and collects metrics.
  6→ */
  7→
  8→import { CipherBoxClient } from '@cipherbox/sdk';
  9→import { setApiClientConfig } from '@cipherbox/api-client';
 10→import { initializeVault, encryptVaultKeys } from '@cipherbox/core';
 11→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 12→import { MetricsCollector } from './metrics';
 13→
 14→const API_URL = process.env.LOAD_TEST_API_URL ?? 'http://localhost:3000';
 15→const SECRET = process.env.LOAD_TEST_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
 16→
 17→export interface PoolClient {
 18→  id: number;
 19→  client: CipherBoxClient;
 20→  accessToken: string;
 21→  publicKey: Uint8Array;
 22→  privateKey: Uint8Array;
 23→  rootIpnsName: string;
 24→  rootFolderKey: Uint8Array;
 25→  rootIpnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 26→  metrics: MetricsCollector;
 27→}
 28→
 29→export interface ClientPoolOptions {
 30→  clientCount: number;
 31→  label: string;
 32→}
 33→
 34→/**
 35→ * Create a pool of N authenticated CipherBoxClient instances.
 36→ *
 37→ * Each client has its own test account, vault, and metrics collector.
 38→ * The api-client singleton is configured once (all clients share baseUrl,
 39→ * tokens are per-request via getAccessToken closure).
 40→ */
 41→export async function createClientPool(opts: ClientPoolOptions): Promise<PoolClient[]> {
 42→  const { clientCount, label } = opts;
 43→  console.log(`Creating ${clientCount} test accounts for "${label}"...`);
 44→  const start = performance.now();
 45→
 46→  // Create accounts in parallel batches of 5 to avoid overwhelming the API
 47→  const clients: PoolClient[] = [];
 48→  const batchSize = 5;
 49→
 50→  for (let batch = 0; batch < clientCount; batch += batchSize) {
 51→    const batchEnd = Math.min(batch + batchSize, clientCount);
 52→    const promises = [];
 53→
 54→    for (let i = batch; i < batchEnd; i++) {
 55→      promises.push(createPoolClient(i, label));
 56→    }
 57→
 58→    const results = await Promise.allSettled(promises);
 59→    for (const result of results) {
 60→      if (result.status === 'fulfilled') {
 61→        clients.push(result.value);
 62→      } else {
 63→        console.warn(`Failed to create pool client: ${result.reason}`);
 64→      }
 65→    }
 66→  }
 67→
 68→  // Configure the singleton once — all clients share the same baseUrl
 69→  // Individual tokens are injected via the getAccessToken closure on each client
 70→  if (clients.length > 0) {
 71→    setApiClientConfig({
 72→      baseUrl: API_URL,
 73→      getAccessToken: async () => clients[0].accessToken,
 74→    });
 75→  }
 76→
 77→  const elapsed = performance.now() - start;
 78→  console.log(
 79→    `Created ${clients.length}/${clientCount} clients in ${(elapsed / 1000).toFixed(1)}s`
 80→  );
 81→
 82→  return clients;
 83→}
 84→
 85→async function createPoolClient(id: number, label: string): Promise<PoolClient> {
 86→  const email = `load-${label}-${id}-${Date.now()}@example.com`;
 87→
 88→  // 1. Authenticate
 89→  const loginRes = await fetch(`${API_URL}/auth/test-login`, {
 90→    method: 'POST',
 91→    headers: { 'Content-Type': 'application/json' },
 92→    body: JSON.stringify({ email, secret: SECRET }),
 93→  });
 94→  if (!loginRes.ok) {
 95→    throw new Error(`test-login failed for client ${id}: ${loginRes.status}`);
 96→  }
 97→  const { accessToken, publicKeyHex, privateKeyHex } = await loginRes.json();
 98→  const publicKey = hexToBytes(publicKeyHex);
 99→  const privateKey = hexToBytes(privateKeyHex);
100→
101→  // 2. Initialize vault
102→  const vault = await initializeVault(privateKey);
103→  const encrypted = await encryptVaultKeys(vault, publicKey);
104→  const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
105→
106→  // 3. Register vault
107→  const initRes = await fetch(`${API_URL}/vault/init`, {
108→    method: 'POST',
109→    headers: {
110→      Authorization: `Bearer ${accessToken}`,
111→      'Content-Type': 'application/json',
112→    },
113→    body: JSON.stringify({
114→      ownerPublicKey: bytesToHex(publicKey),
115→      encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
116→      encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
117→      rootIpnsName,
118→    }),
119→  });
120→  if (!initRes.ok) {
121→    throw new Error(`vault/init failed for client ${id}: ${initRes.status}`);
122→  }
123→
124→  // 4. Create CipherBoxClient
125→  const client = new CipherBoxClient({
126→    apiUrl: API_URL,
127→    getAccessToken: async () => accessToken,
128→    vaultKeypair: { publicKey, privateKey },
129→    rootIpnsName,
130→    rootFolderKey: vault.rootFolderKey,
131→  });
132→  client.registerFolder(rootIpnsName, vault.rootFolderKey, vault.rootIpnsKeypair, [], 0n);
133→
134→  return {
135→    id,
136→    client,
137→    accessToken,
138→    publicKey,
139→    privateKey,
140→    rootIpnsName,
141→    rootFolderKey: vault.rootFolderKey,
142→    rootIpnsKeypair: vault.rootIpnsKeypair,
143→    metrics: new MetricsCollector(),
144→  };
145→}
146→
147→/**
148→ * Destroy all clients in the pool and delete test accounts.
149→ */
150→export async function destroyClientPool(pool: PoolClient[]): Promise<void> {
151→  console.log(`Cleaning up ${pool.length} test accounts...`);
152→  for (const pc of pool) {
153→    pc.client.destroy();
154→    try {
155→      await fetch(`${API_URL}/auth/account`, {
156→        method: 'DELETE',
157→        headers: {
158→          Authorization: `Bearer ${pc.accessToken}`,
159→          'Content-Type': 'application/json',
160→        },
161→        body: JSON.stringify({ confirmation: 'DELETE' }),
162→      });
163→    } catch {
164→      // Best-effort cleanup
165→    }
166→  }
167→}
