 1→/**
 2→ * Domain-specific assertion helpers for SDK E2E tests.
 3→ */
 4→
 5→import { expect } from 'vitest';
 6→import type { CipherBoxClient } from '@cipherbox/sdk';
 7→
 8→/**
 9→ * Assert that a folder's in-memory children contain an item with the given name.
10→ */
11→export function expectChildNamed(
12→  client: CipherBoxClient,
13→  folderIpnsName: string,
14→  name: string
15→): void {
16→  const folder = (client as any).folderTree.get(folderIpnsName);
17→  expect(folder, `Folder ${folderIpnsName} not found in tree`).toBeTruthy();
18→  const match = folder.children.find((c: any) => c.name === name);
19→  expect(match, `Expected child named "${name}" in folder`).toBeTruthy();
20→}
21→
22→/**
23→ * Assert that a folder does NOT contain an item with the given name.
24→ */
25→export function expectNoChildNamed(
26→  client: CipherBoxClient,
27→  folderIpnsName: string,
28→  name: string
29→): void {
30→  const folder = (client as any).folderTree.get(folderIpnsName);
31→  expect(folder, `Folder ${folderIpnsName} not found in tree`).toBeTruthy();
32→  const match = folder.children.find((c: any) => c.name === name);
33→  expect(match, `Expected no child named "${name}" in folder`).toBeUndefined();
34→}
35→
36→/**
37→ * Assert that a folder has exactly N children.
38→ */
39→export function expectChildCount(
40→  client: CipherBoxClient,
41→  folderIpnsName: string,
42→  count: number
43→): void {
44→  const folder = (client as any).folderTree.get(folderIpnsName);
45→  expect(folder, `Folder ${folderIpnsName} not found in tree`).toBeTruthy();
46→  expect(folder.children.length).toBe(count);
47→}
48→
49→/**
50→ * Get a child entry from the folder tree by name.
51→ * Throws if not found.
52→ */
53→export function getChild(client: CipherBoxClient, folderIpnsName: string, name: string): any {
54→  const folder = (client as any).folderTree.get(folderIpnsName);
55→  if (!folder) throw new Error(`Folder ${folderIpnsName} not in tree`);
56→  const match = folder.children.find((c: any) => c.name === name);
57→  if (!match) throw new Error(`Child "${name}" not found in folder`);
58→  return match;
59→}
60→
61→/**
62→ * Get all children from the folder tree.
63→ */
64→export function getChildren(client: CipherBoxClient, folderIpnsName: string): any[] {
65→  const folder = (client as any).folderTree.get(folderIpnsName);
66→  if (!folder) throw new Error(`Folder ${folderIpnsName} not in tree`);
67→  return folder.children;
68→}
