137→
138→    it('should emit error events on failure', async () => {
139→      const events: any[] = [];
140→      const unsub = ctx.client.on((event) => events.push(event));
141→
142→      try {
143→        await ctx.client.createFolder('k51nonexistent', 'WillFail');
144→      } catch {
145→        // Expected
146→      }
147→
148→      unsub();
149→
150→      const errors = events.filter((e) => e.type === 'error');
151→      expect(errors.length).toBe(1);
152→      expect(errors[0].operation).toBe('createFolder');
153→      expect(errors[0].error).toBeInstanceOf(Error);
