 1→/**
 2→ * Multi-Account Test Fixture
 3→ *
 4→ * Creates N test accounts for tests that require interaction between users
 5→ * (sharing, invite links). Handles the setApiClientConfig singleton caveat
 6→ * by switching the active account before each operation.
 7→ */
 8→
 9→import { setApiClientConfig } from '@cipherbox/api-client';
10→import { createTestContext, deleteTestAccount, type TestContext, API_URL } from './test-harness';
11→
12→export interface MultiAccountFixture {
13→  /** All created test contexts, indexed by label */
14→  accounts: Map<string, TestContext>;
15→  /**
16→   * Switch the api-client singleton to the given account.
17→   * Must be called before any operation that uses the singleton
18→   * (e.g., sdk-core IPNS functions).
19→   */
20→  switchTo: (label: string) => void;
21→  /** Destroy all clients and delete all accounts */
22→  cleanupAll: () => Promise<void>;
23→}
24→
25→/**
26→ * Create N test accounts with the given labels.
27→ *
28→ * @example
29→ * const fixture = await createMultiAccountFixture(['alice', 'bob']);
30→ * const alice = fixture.accounts.get('alice')!;
31→ * const bob = fixture.accounts.get('bob')!;
32→ */
33→export async function createMultiAccountFixture(labels: string[]): Promise<MultiAccountFixture> {
34→  const accounts = new Map<string, TestContext>();
35→
36→  // Create accounts sequentially to avoid race conditions on vault init
37→  for (const label of labels) {
38→    const ctx = await createTestContext(label);
39→    accounts.set(label, ctx);
40→  }
41→
42→  const switchTo = (label: string): void => {
43→    const ctx = accounts.get(label);
44→    if (!ctx) throw new Error(`No account with label "${label}"`);
45→    setApiClientConfig({
46→      baseUrl: API_URL,
47→      getAccessToken: async () => ctx.accessToken,
48→    });
49→  };
50→
51→  const cleanupAll = async (): Promise<void> => {
52→    for (const [, ctx] of accounts) {
53→      ctx.cleanup();
54→      await deleteTestAccount(ctx);
55→    }
56→    accounts.clear();
57→  };
58→
59→  return { accounts, switchTo, cleanupAll };
60→}
61→

 1→/**
 2→ * File Upload/Download Workload
 3→ *
 4→ * Parameterized workload that uploads and downloads files of varying sizes.
 5→ */
 6→
 7→import type { PoolClient } from '../harness/client-pool';
 8→
 9→export interface FileWorkloadOptions {
10→  /** Number of files to upload */
11→  fileCount: number;
12→  /** Min file size in bytes */
13→  minSize: number;
14→  /** Max file size in bytes */
15→  maxSize: number;
16→  /** Whether to verify downloads after upload */
17→  verifyDownloads: boolean;
18→}
19→
20→/**
21→ * Run a file upload workload on a single client.
22→ */
23→export async function runFileWorkload(pc: PoolClient, opts: FileWorkloadOptions): Promise<void> {
24→  const { fileCount, minSize, maxSize, verifyDownloads } = opts;
25→  const { client, rootIpnsName, rootFolderKey, metrics } = pc;
26→
27→  for (let i = 0; i < fileCount; i++) {
28→    const size = minSize + Math.floor(Math.random() * (maxSize - minSize));
29→    const data = new Uint8Array(size);
30→    crypto.getRandomValues(data);
31→    const fileName = `load-${pc.id}-file-${i}-${size}b.bin`;
32→
33→    // Upload
34→    await metrics.measure(
35→      'uploadFile',
36→      () => client.uploadFile(rootIpnsName, data, fileName, 'application/octet-stream'),
37→      size
38→    );
39→
40→    // Optionally download and verify
41→    if (verifyDownloads) {
42→      const folder = (client as any).folderTree.get(rootIpnsName);
43→      const child = folder?.children.find((c: any) => c.name === fileName);
44→      if (child?.fileMetaIpnsName) {
45→        const downloaded = await metrics.measure(
46→          'downloadFile',
47→          () => client.downloadFromIpns(child.fileMetaIpnsName, rootFolderKey),
48→          size
49→        );
50→        if (downloaded.length !== data.length) {
51→          throw new Error(
52→            `Size mismatch: uploaded ${data.length}, downloaded ${downloaded.length}`
53→          );
54→        }
55→      }
56→    }
57→  }
58→}
59→

 1→/**
 2→ * Folder CRUD Workload
 3→ *
 4→ * Creates, renames, moves, and deletes folders.
 5→ */
 6→
 7→import type { PoolClient } from '../harness/client-pool';
 8→
 9→export interface FolderWorkloadOptions {
10→  /** Number of folder create-rename-delete cycles */
11→  cycles: number;
12→}
13→
14→/**
15→ * Run a folder CRUD workload on a single client.
16→ */
17→export async function runFolderWorkload(
18→  pc: PoolClient,
19→  opts: FolderWorkloadOptions
20→): Promise<void> {
21→  const { client, rootIpnsName, metrics } = pc;
22→
23→  for (let i = 0; i < opts.cycles; i++) {
24→    const name = `load-folder-${pc.id}-${i}`;
25→
26→    // Create
27→    const folder = await metrics.measure('createFolder', () =>
28→      client.createFolder(rootIpnsName, name)
29→    );
30→
31→    // Rename
32→    await metrics.measure('renameItem', () =>
33→      client.renameItem(rootIpnsName, folder.id, `${name}-renamed`)
34→    );
35→
36→    // Delete
37→    await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, folder.id));
38→  }
39→}
