  1→/**
  2→ * Spike Test Scenario
  3→ *
  4→ * Starts with a baseline of 2 clients, then bursts to 20 clients.
  5→ * Measures recovery time — how long until latencies return to baseline.
  6→ */
  7→
  8→import { describe, it, afterAll } from 'vitest';
  9→import { createClientPool, destroyClientPool, type PoolClient } from '../harness/client-pool';
 10→import { MetricsCollector } from '../harness/metrics';
 11→import { printSummary, toJsonReport } from '../harness/reporter';
 12→import { runFolderWorkload } from '../workloads/folder-workload';
 13→
 14→const BASELINE_CLIENTS = 2;
 15→const BURST_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '20', 10);
 16→const BASELINE_CYCLES = 10;
 17→const BURST_CYCLES = 30;
 18→
 19→describe('Spike Test', () => {
 20→  let baselinePool: PoolClient[] = [];
 21→  let burstPool: PoolClient[] = [];
 22→
 23→  afterAll(async () => {
 24→    await destroyClientPool(baselinePool);
 25→    await destroyClientPool(burstPool);
 26→  });
 27→
 28→  it(`baseline ${BASELINE_CLIENTS} clients → burst ${BURST_CLIENTS} clients`, async () => {
 29→    // Phase 1: Baseline
 30→    console.log('\n--- Phase 1: Baseline ---');
 31→    baselinePool = await createClientPool({
 32→      clientCount: BASELINE_CLIENTS,
 33→      label: 'spike-baseline',
 34→    });
 35→
 36→    const baselineStart = Date.now();
 37→    await Promise.allSettled(
 38→      baselinePool.map((pc) => {
 39→        pc.metrics.start();
 40→        return runFolderWorkload(pc, { cycles: BASELINE_CYCLES }).finally(() => pc.metrics.stop());
 41→      })
 42→    );
 43→    const baselineDuration = Date.now() - baselineStart;
 44→
 45→    const baselineMetrics = new MetricsCollector();
 46→    baselineMetrics.start();
 47→    for (const pc of baselinePool) {
 48→      for (const sample of pc.metrics.getRawSamples()) {
 49→        baselineMetrics.record(sample);
 50→      }
 51→    }
 52→    baselineMetrics.stop();
 53→
 54→    printSummary(
 55→      'Spike Test - Baseline',
 56→      baselineMetrics.getMetrics(),
 57→      baselineDuration,
 58→      BASELINE_CLIENTS
 59→    );
 60→
 61→    // Phase 2: Burst
 62→    console.log('\n--- Phase 2: Burst ---');
 63→    burstPool = await createClientPool({
 64→      clientCount: BURST_CLIENTS,
 65→      label: 'spike-burst',
 66→    });
 67→
 68→    const burstStart = Date.now();
 69→    await Promise.allSettled(
 70→      burstPool.map((pc) => {
 71→        pc.metrics.start();
 72→        return runFolderWorkload(pc, { cycles: BURST_CYCLES }).finally(() => pc.metrics.stop());
 73→      })
 74→    );
 75→    const burstDuration = Date.now() - burstStart;
 76→
 77→    const burstMetrics = new MetricsCollector();
 78→    burstMetrics.start();
 79→    for (const pc of burstPool) {
 80→      for (const sample of pc.metrics.getRawSamples()) {
 81→        burstMetrics.record(sample);
 82→      }
 83→    }
 84→    burstMetrics.stop();
 85→
 86→    printSummary('Spike Test - Burst', burstMetrics.getMetrics(), burstDuration, BURST_CLIENTS);
 87→
 88→    // Compare baseline vs burst latencies
 89→    const baselineOps = baselineMetrics.getMetrics();
 90→    const burstOps = burstMetrics.getMetrics();
 91→
 92→    console.log('\n--- Latency Comparison (p95) ---');
 93→    for (const baseOp of baselineOps) {
 94→      const burstOp = burstOps.find((b) => b.operation === baseOp.operation);
 95→      if (burstOp) {
 96→        const degradation = (
 97→          ((burstOp.latency.p95 - baseOp.latency.p95) / baseOp.latency.p95) *
 98→          100
 99→        ).toFixed(0);
100→        console.log(
101→          `  ${baseOp.operation}: baseline=${Math.round(baseOp.latency.p95)}ms → burst=${Math.round(burstOp.latency.p95)}ms (${degradation}% change)`
102→        );
103→      }
104→    }
105→
106→    // JSON for both phases
107→    console.log(
108→      '\nJSON Report (Burst):\n' +
109→        toJsonReport('spike-test-burst', burstOps, burstDuration, BURST_CLIENTS)
110→    );
111→  });
112→});
