  1→/**
  2→ * Mixed Workload
  3→ *
  4→ * Simulates realistic usage: a mix of folder CRUD, file uploads,
  5→ * renames, moves, and deletes with weighted probabilities.
  6→ */
  7→
  8→import type { PoolClient } from '../harness/client-pool';
  9→
 10→export interface MixedWorkloadOptions {
 11→  /** Total number of operations */
 12→  totalOps: number;
 13→  /** Operation weights (sum doesn't need to be 1, they're normalized) */
 14→  weights?: {
 15→    createFolder?: number;
 16→    uploadFile?: number;
 17→    renameItem?: number;
 18→    moveItem?: number;
 19→    deleteItem?: number;
 20→  };
 21→}
 22→
 23→const DEFAULT_WEIGHTS = {
 24→  createFolder: 2,
 25→  uploadFile: 4,
 26→  renameItem: 1,
 27→  moveItem: 1,
 28→  deleteItem: 1,
 29→};
 30→
 31→/**
 32→ * Run a mixed workload on a single client.
 33→ */
 34→export async function runMixedWorkload(pc: PoolClient, opts: MixedWorkloadOptions): Promise<void> {
 35→  const { client, rootIpnsName, metrics } = pc;
 36→  const weights = { ...DEFAULT_WEIGHTS, ...opts.weights };
 37→  const totalWeight = Object.values(weights).reduce((a, b) => a + b, 0);
 38→
 39→  // Track created items for rename/move/delete targets
 40→  const folderIds: Array<{
 41→    id: string;
 42→    ipnsName: string;
 43→    folderKey: Uint8Array;
 44→    ipnsPrivateKey: Uint8Array;
 45→  }> = [];
 46→  const fileIds: Array<{ id: string; name: string }> = [];
 47→
 48→  for (let i = 0; i < opts.totalOps; i++) {
 49→    const roll = Math.random() * totalWeight;
 50→    let cumulative = 0;
 51→
 52→    // Pick operation based on weighted random
 53→    if ((cumulative += weights.createFolder) > roll) {
 54→      // Create folder
 55→      try {
 56→        const name = `mix-folder-${pc.id}-${i}`;
 57→        const folder = await metrics.measure('createFolder', () =>
 58→          client.createFolder(rootIpnsName, name)
 59→        );
 60→        folderIds.push(folder);
 61→      } catch {
 62→        /* non-fatal */
 63→      }
 64→    } else if ((cumulative += weights.uploadFile) > roll) {
 65→      // Upload file
 66→      try {
 67→        const size = 1024 + Math.floor(Math.random() * 50_000);
 68→        const data = new Uint8Array(size);
 69→        crypto.getRandomValues(data);
 70→        const fileName = `mix-file-${pc.id}-${i}.bin`;
 71→
 72→        await metrics.measure(
 73→          'uploadFile',
 74→          () => client.uploadFile(rootIpnsName, data, fileName, 'application/octet-stream'),
 75→          size
 76→        );
 77→
 78→        const folder = (client as any).folderTree.get(rootIpnsName);
 79→        const child = folder?.children.find((c: any) => c.name === fileName);
 80→        if (child) fileIds.push({ id: child.id, name: fileName });
 81→      } catch {
 82→        /* non-fatal */
 83→      }
 84→    } else if ((cumulative += weights.renameItem) > roll) {
 85→      // Rename a random file
 86→      if (fileIds.length > 0) {
 87→        const idx = Math.floor(Math.random() * fileIds.length);
 88→        const target = fileIds[idx];
 89→        const newName = `${target.name}-r${i}`;
 90→        try {
 91→          await metrics.measure('renameItem', () =>
 92→            client.renameItem(rootIpnsName, target.id, newName)
 93→          );
 94→          fileIds[idx] = { ...target, name: newName };
 95→        } catch {
 96→          /* non-fatal */
 97→        }
 98→      }
 99→    } else if ((cumulative += weights.moveItem) > roll) {
100→      // Move a file into a folder (if both exist)
101→      if (fileIds.length > 0 && folderIds.length > 0) {
102→        const fileIdx = Math.floor(Math.random() * fileIds.length);
103→        const folderIdx = Math.floor(Math.random() * folderIds.length);
104→        const targetFolder = folderIds[folderIdx];
105→
106→        // Ensure target folder is registered
107→        if (!client.hasFolder(targetFolder.ipnsName)) {
108→          client.registerFolder(
109→            targetFolder.ipnsName,
110→            targetFolder.folderKey,
111→            { publicKey: new Uint8Array(0), privateKey: targetFolder.ipnsPrivateKey },
112→            [],
113→            1n
114→          );
115→        }
116→
117→        try {
118→          await metrics.measure('moveItem', () =>
119→            client.moveItem(rootIpnsName, targetFolder.ipnsName, fileIds[fileIdx].id)
120→          );
121→          fileIds.splice(fileIdx, 1); // Remove from root tracking
122→        } catch {
123→          /* non-fatal */
124→        }
125→      }
126→    } else {
127→      // Delete a random item
128→      if (fileIds.length > 0) {
129→        const idx = Math.floor(Math.random() * fileIds.length);
130→        try {
131→          await metrics.measure('deleteItem', () =>
132→            client.deleteItem(rootIpnsName, fileIds[idx].id)
133→          );
134→          fileIds.splice(idx, 1);
135→        } catch {
136→          /* non-fatal */
137→        }
138→      } else if (folderIds.length > 0) {
139→        const idx = Math.floor(Math.random() * folderIds.length);
140→        try {
141→          await metrics.measure('deleteItem', () =>
142→            client.deleteItem(rootIpnsName, folderIds[idx].id)
143→          );
144→          folderIds.splice(idx, 1);
145→        } catch {
146→          /* non-fatal */
147→        }
148→      }
149→    }
150→  }
151→}
