  1→/**
  2→ * Sustained Load Scenario
  3→ *
  4→ * N clients running at a steady rate for a configurable duration.
  5→ * Tests latency stability over time — detects memory leaks, connection
  6→ * pool exhaustion, and other time-dependent degradation.
  7→ */
  8→
  9→import { describe, it, afterAll } from 'vitest';
 10→import { createClientPool, destroyClientPool, type PoolClient } from '../harness/client-pool';
 11→import { MetricsCollector } from '../harness/metrics';
 12→import { printSummary, toJsonReport } from '../harness/reporter';
 13→
 14→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
 15→const DURATION_SEC = parseInt(process.env.LOAD_TEST_DURATION ?? '300', 10);
 16→const OPS_PER_SEC_PER_CLIENT = 2;
 17→
 18→describe('Sustained Load', () => {
 19→  let pool: PoolClient[] = [];
 20→
 21→  afterAll(async () => {
 22→    await destroyClientPool(pool);
 23→  });
 24→
 25→  it(`${NUM_CLIENTS} clients × ${OPS_PER_SEC_PER_CLIENT} ops/sec for ${DURATION_SEC}s`, async () => {
 26→    pool = await createClientPool({
 27→      clientCount: NUM_CLIENTS,
 28→      label: 'sustained',
 29→    });
 30→
 31→    const endTime = Date.now() + DURATION_SEC * 1000;
 32→
 33→    const results = await Promise.allSettled(
 34→      pool.map((pc) => runSustainedClient(pc, endTime, OPS_PER_SEC_PER_CLIENT))
 35→    );
 36→
 37→    // Aggregate
 38→    const allMetrics = new MetricsCollector();
 39→    allMetrics.start();
 40→    for (const pc of pool) {
 41→      for (const sample of pc.metrics.getRawSamples()) {
 42→        allMetrics.record(sample);
 43→      }
 44→    }
 45→    allMetrics.stop();
 46→
 47→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
 48→    console.log(`\nClients completed: ${succeeded}/${pool.length}`);
 49→
 50→    const metrics = allMetrics.getMetrics();
 51→    const samples = pool.flatMap((pc) => pc.metrics.getRawSamples());
 52→    const totalDuration =
 53→      samples.length > 0
 54→        ? Math.max(...samples.map((s) => s.timestamp)) -
 55→          Math.min(...samples.map((s) => s.timestamp))
 56→        : 0;
 57→
 58→    printSummary('Sustained Load', metrics, totalDuration, pool.length);
 59→    console.log(
 60→      '\nJSON Report:\n' + toJsonReport('sustained-load', metrics, totalDuration, pool.length)
 61→    );
 62→  });
 63→});
 64→
 65→async function runSustainedClient(
 66→  pc: PoolClient,
 67→  endTime: number,
 68→  opsPerSec: number
 69→): Promise<void> {
 70→  const { client, rootIpnsName, metrics } = pc;
 71→  metrics.start();
 72→
 73→  const intervalMs = 1000 / opsPerSec;
 74→  let folderCounter = 0;
 75→
 76→  while (Date.now() < endTime) {
 77→    const opStart = Date.now();
 78→
 79→    try {
 80→      // Alternate between folder create and delete to keep state manageable
 81→      const name = `sustained-${pc.id}-${folderCounter++}`;
 82→
 83→      const folder = await metrics.measure('createFolder', () =>
 84→        client.createFolder(rootIpnsName, name)
 85→      );
 86→
 87→      // Small file upload
 88→      const data = new Uint8Array(1024);
 89→      crypto.getRandomValues(data);
 90→      await metrics.measure(
 91→        'uploadFile',
 92→        () => client.uploadFile(rootIpnsName, data, `${name}.bin`, 'application/octet-stream'),
 93→        1024
 94→      );
 95→
 96→      // Cleanup to prevent state bloat
 97→      const folderState = (client as any).folderTree.get(rootIpnsName);
 98→      const fileChild = folderState?.children.find((c: any) => c.name === `${name}.bin`);
 99→      if (fileChild) {
100→        await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, fileChild.id));
101→      }
102→      await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, folder.id));
103→    } catch {
104→      // Non-fatal — continue the sustained load
105→    }
106→
107→    // Wait for next interval
108→    const elapsed = Date.now() - opStart;
109→    const wait = Math.max(0, intervalMs - elapsed);
110→    if (wait > 0) {
111→      await new Promise((r) => setTimeout(r, wait));
112→    }
113→  }
114→
115→  metrics.stop();
116→}
