  1→import axios, {
  2→  type AxiosInstance,
  3→  type AxiosRequestConfig,
  4→  type AxiosError,
  5→  type AxiosProgressEvent,
  6→  type CancelToken,
  7→} from 'axios';
  8→
  9→export type ApiClientConfig = {
 10→  /** Base URL for the CipherBox API (e.g., "http://localhost:3000") */
 11→  baseUrl: string;
 12→  /** Returns a valid access token. Consumer owns refresh logic. */
 13→  getAccessToken: () => Promise<string>;
 14→  /** Called on 401 response to obtain a new access token. If provided, the failed request is retried once with the new token. */
 15→  refreshAccessToken?: () => Promise<string>;
 16→  /** Send cookies cross-origin (needed for HTTP-only refresh token cookie in web). */
 17→  withCredentials?: boolean;
 18→  /** Called when token refresh fails (e.g., clear stores, redirect to login). */
 19→  onRefreshFailure?: () => void;
 20→};
 21→
 22→/**
 23→ * Create a configured axios instance for CipherBox API calls.
 24→ * No Zustand, no import.meta.env -- all config injected by consumer.
 25→ */
 26→export function createAxiosInstance(config: ApiClientConfig): AxiosInstance {
 27→  const instance = axios.create({
 28→    baseURL: config.baseUrl,
 29→    withCredentials: config.withCredentials ?? false,
 30→  });
 31→  instance.interceptors.request.use(async (reqConfig) => {
 32→    const token = await config.getAccessToken();
 33→    if (token) {
 34→      reqConfig.headers.set('Authorization', `Bearer ${token}`);
 35→    }
 36→    return reqConfig;
 37→  });
 38→  return instance;
 39→}
 40→
 41→/**
 42→ * Custom instance function for orval-generated code.
 43→ * Matches the signature orval expects from a mutator.
 44→ * The consumer must call setApiClientConfig() before using generated functions.
 45→ */
 46→let _config: ApiClientConfig | null = null;
 47→let _instance: AxiosInstance | null = null;
 48→
 49→export function setApiClientConfig(config: ApiClientConfig): void {
 50→  _config = config;
 51→  _instance = null; // Reset cached instance when config changes
 52→}
 53→
 54→export function getApiClientConfig(): ApiClientConfig {
 55→  if (!_config) throw new Error('API client not configured. Call setApiClientConfig() first.');
 56→  return _config;
 57→}
 58→
 59→// Shared refresh promise eliminates race condition where multiple concurrent
 60→// 401 responses each trigger their own refresh before the first completes.
 61→let _refreshPromise: Promise<string> | null = null;
 62→
 63→function getCachedInstance(): AxiosInstance {
 64→  if (!_instance) {
 65→    const clientConfig = getApiClientConfig();
 66→    _instance = axios.create({
 67→      baseURL: clientConfig.baseUrl,
 68→      withCredentials: clientConfig.withCredentials ?? false,
 69→    });
 70→
 71→    // 401 response interceptor: refresh token and retry once
 72→    if (clientConfig.refreshAccessToken) {
 73→      const refreshFn = clientConfig.refreshAccessToken;
 74→      const onFailure = clientConfig.onRefreshFailure;
 75→
 76→      _instance.interceptors.response.use(
 77→        (response) => response,
 78→        async (error: AxiosError) => {
 79→          const originalRequest = error.config as
 80→            | (AxiosRequestConfig & { _retry?: boolean })
 81→            | undefined;
 82→          if (!originalRequest) throw error;
 83→
 84→          // Don't retry refresh endpoint to avoid infinite loop
 85→          const isRefreshRequest = originalRequest.url?.includes('/auth/refresh');
 86→
 87→          if (error.response?.status === 401 && !originalRequest._retry && !isRefreshRequest) {
 88→            originalRequest._retry = true;
 89→
 90→            if (!_refreshPromise) {
 91→              // First 401 handler: create the refresh promise synchronously
 92→              _refreshPromise = refreshFn()
 93→                .catch((refreshError) => {
 94→                  onFailure?.();
 95→                  throw refreshError;
 96→                })
 97→                .finally(() => {
 98→                  _refreshPromise = null;
 99→                });
100→            }
101→
102→            // All concurrent 401 handlers await the same promise.
103→            const token = await _refreshPromise;
104→            originalRequest.headers = originalRequest.headers ?? {};
105→            originalRequest.headers['Authorization'] = `Bearer ${token}`;
106→            return getCachedInstance().request(originalRequest);
107→          }
108→
109→          throw error;
110→        }
111→      );
112→    }
113→  }
114→  return _instance;
115→}
116→
117→export const customInstance = async <T>(
118→  config: AxiosRequestConfig,
119→  options?: AxiosRequestConfig
120→): Promise<T> => {
121→  const clientConfig = getApiClientConfig();
122→  const token = await clientConfig.getAccessToken();
123→  const instance = getCachedInstance();
124→
125→  const response = await instance.request<T>({
126→    ...config,
127→    ...options,
128→    headers: {
129→      ...config.headers,
130→      ...options?.headers,
131→      ...(token ? { Authorization: `Bearer ${token}` } : {}),
132→    },
133→  });
134→
135→  return response.data;
136→};
137→
138→export default customInstance;
139→
140→export type ErrorType<Error> = AxiosError<Error>;
141→export type BodyType<BodyData> = BodyData;
142→
143→// Re-export axios types that consumers need for IPFS upload (progress, cancel)
144→export type { AxiosInstance, AxiosProgressEvent, CancelToken };
145→export { default as axios } from 'axios';
